r=[]
r.append(R(6571015,"जैलापेनो चिकन और मक्के का चाउडर",
"यह भरपेट मुख्य व्यंजन चाउडर बड़े-बड़े टुकड़ों के स्वाद से भरा है, जिसमें मीठा मक्का और रसीला चिकन शामिल है। जैलापेनो मिर्च इसमें हल्का तीखापन जोड़ती है। गर्मियों के एकदम सही भोजन के लिए इसे हल्के अरुगुला सलाद और ताज़े तरबूज़ की एक सर्विंग, या इस तरबूज़, अरुगुला और फ़ेटा सलाद के साथ परोसें।",
"8","1 1/4 कप",
["1 बड़ा चम्मच जैतून का तेल","1 मध्यम पीला प्याज़ (छिला और कटा हुआ)","2 मध्यम गाजर (छिली और कटी हुई)","2 डंठल अजवाइन (सेलरी) (कटे हुए)","2 मध्यम जैलापेनो मिर्च (बीज निकाली हुई और कटी हुई)","2 कली लहसुन (छिली और कुचली हुई)","4 मध्यम भुट्टे स्वीट कॉर्न (दाने भुट्टे से काटे हुए, या 4 कप जमे हुए दाने, पिघलाए और पानी निथारे हुए)","1 बड़ा चम्मच बिना नमक वाली सीज़निंग","1/2 छोटा चम्मच काली मिर्च","4 कप फ़ैट-फ़्री, कम सोडियम वाला चिकन ब्रॉथ","2 कप पका हुआ चिकन ब्रेस्ट (कटा हुआ)","1 कप सादा फ़ैट-फ़्री ग्रीक योगर्ट"],
["एक बड़े सूप के बर्तन में मध्यम आँच पर तेल गरम करें। प्याज़, गाजर, अजवाइन, जैलापेनो, लहसुन और मक्का डालें और 5 से 7 मिनट भूनें।","बिना नमक वाली सीज़निंग, काली मिर्च और चिकन ब्रॉथ डालें। उबाल आने दें, फिर आँच कम करें और ढककर 20 मिनट धीमी आँच पर पकाएँ।","बर्तन को आँच से उतारें और इमर्शन ब्लेंडर या खड़े ब्लेंडर से लगभग आधे सूप की प्यूरी बनाएँ। अगर खड़े ब्लेंडर का उपयोग कर रहे हैं, तो कई बार में प्यूरी बनाएँ और ब्लेंडर को ज़्यादा न भरें। प्यूरी को वापस बर्तन में डालें।","चिकन डालें और अंदर तक गरम करें। बर्तन को आँच से उतार लें।","योगर्ट मिलाएँ और परोसें। योगर्ट डालने के बाद सूप को न उबालें।"]))
r.append(R(6571661,"राजमा स्ट्यू",
"फलियाँ लैटिन व्यंजनों का मुख्य हिस्सा हैं: क्यूबाई काली बीन्स, मैक्सिकन रिफ़्राइड पिंटो बीन्स, आदि। ये लाल राजमा प्यूर्टो रिकन और डोमिनिकन व्यंजनों में लोकप्रिय हैं।",
"6","1/2 कप",
["1 बड़ा चम्मच जैतून का तेल","1 मध्यम प्याज़ (बारीक कटा हुआ)","1 बड़ी लाल शिमला मिर्च (टुकड़ों में कटी हुई)","2 कली लहसुन (बारीक कटी हुई)","1 कप (लगभग 7 औंस) छिला, चौकोर कटा कद्दू या बटरनट स्क्वैश","1 (15.5 औंस) डिब्बा बिना नमक मिलाया लाल राजमा (धुला और पानी निथारा हुआ)","1 1/2 कप बिना नमक का चिकन ब्रॉथ","1/4 कप बिना नमक मिलाया टमाटर सॉस","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/4 कप कटी हुई धनिया पत्ती"],
["एक बड़ी नॉनस्टिक कड़ाही में मध्यम-तेज़ आँच पर तेल गरम करें। प्याज़, शिमला मिर्च और लहसुन डालें और बीच-बीच में चलाते हुए पकाएँ, जब तक सब्ज़ियाँ नरम न हो जाएँ, लगभग 8 मिनट।","कद्दू, राजमा, ब्रॉथ, टमाटर सॉस, नमक और काली मिर्च डालें और उबाल आने दें। आँच को मध्यम कर दें। ढककर तब तक पकाएँ जब तक कद्दू नरम न हो जाए, 10–12 मिनट। धनिया पत्ती डालकर चलाएँ।"]))
r.append(R(6572091,"क्यूबानो भुने हुए ब्रोकली के फूल",
"क्या आप कम कार्ब वाली साइड डिश ढूँढ रहे हैं जो मुख्य प्रोटीन के साथ बढ़िया जमे, प्लेट मेथड का अहम हिस्सा बन सके, और पोषक तत्वों से भरपूर सुपरफ़ूड में थोड़ा तीखापन जोड़े? शेफ़ रोनाल्डो लिनारेस की यह सरल भुनी हुई ब्रोकली का व्यंजन यह काम कर देगा। जीरा और नीबू मसाला और खट्टापन जोड़कर कैरिबियन स्वाद देते हैं और एवोकाडो का तेल व्यंजन में स्वस्थ, हृदय के अनुकूल वसा भरता है। इसे शेफ़ रोनाल्डो के मोहो मैरिनेटेड पोर्क और फूलगोभी के चावल के सलाद के साथ परोसें और आपको मिलेगा एक भरपेट, कम कार्ब वाला भोजन जो किसी द्वीप की छुट्टी के लायक है।",
"4","1 कप",
["3 कली लहसुन (छिली हुई और पतली स्लाइस में कटी हुई)","1/4 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच नीबू का रस","1/8 छोटा चम्मच काली मिर्च","1/2 कप स्पैनिश प्याज़ (पतले स्लाइस में कटा हुआ)","2 छोटे चम्मच एवोकाडो तेल","16 औंस ब्रोकली के फूल","1 बेकिंग पेपर"],
["ओवन को 350°F पर पहले से गरम करें।","एक कटोरे में लहसुन, जीरा, नीबू का रस, काली मिर्च और प्याज़ मिलाएँ। सामग्री को अच्छी तरह मिलाएँ ताकि मसाला बराबर फैल जाए। कटोरे में एवोकाडो तेल और ब्रोकली के फूल डालें और फिर मिलाएँ।","सारी सामग्री को बेकिंग पेपर बिछी बेकिंग शीट पर रखें और 25 मिनट भूनें।","ओवन से निकालें, और काँटा उठाएँ ताकि आप इस स्वादिष्ट व्यंजन का आनंद ले सकें।"]))
r.append(R(6575594,"भूमध्यसागरीय बेक्ड बैंगन",
"पोषक तत्वों से भरपूर बैंगन को इस आसान साइड डिश रेसिपी में भूमध्यसागरीय अंदाज़ में नया रूप दिया गया है। ताज़े टमाटर, चूरा किया फ़ेटा चीज़ और जड़ी-बूटियाँ इस मधुमेह के अनुकूल व्यंजन को स्वाद के अगले स्तर पर ले जाते हैं।",
"4","3/4 कप",
["1 मध्यम बैंगन (गोल स्लाइस में कटा हुआ)","2 बड़े चम्मच जैतून का तेल","2 कली लहसुन (बारीक कटी हुई)","1 छोटा चम्मच सूखा ओरेगानो","1 छोटा चम्मच सूखा थाइम","1/2 छोटा चम्मच स्मोक्ड पैपरिका","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 कप चेरी टमाटर (आधे कटे हुए)","1/4 कप फ़ेटा चीज़ (कम वसा वाला, चूरा किया हुआ)","2 बड़े चम्मच ताज़ा अजमोद (पत्तियाँ, सजाने के लिए)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","बैंगन के गोल स्लाइस को बेकिंग शीट पर रखें।","एक छोटे कटोरे में जैतून का तेल, कटा हुआ लहसुन, सूखा ओरेगानो, सूखा थाइम, स्मोक्ड पैपरिका, नमक और काली मिर्च फेंटकर मिलाएँ।","बैंगन के हर गोल स्लाइस के दोनों तरफ़ जैतून के तेल का मिश्रण ब्रश से लगाएँ।","पहले से गरम ओवन में 15 मिनट बेक करें, फिर बैंगन के गोलों को पलटें और 15 मिनट और बेक करें, या जब तक वे नरम और सुनहरे भूरे न हो जाएँ।","बैंगन को ओवन से निकालें।","बेक किए बैंगन पर आधे कटे चेरी टमाटर और चूरा किया फ़ेटा चीज़ छिड़कें।","बेकिंग शीट को वापस ओवन में रखें और 5 मिनट और बेक करें, या जब तक फ़ेटा नरम न हो जाए और टमाटर हल्के भुन न जाएँ।"]))
r.append(R(6576870,"टूना सेविचे",
"सेविचे एक लैटिन व्यंजन है जो पारंपरिक रूप से खट्टे फलों के रस में मैरिनेट और क्योर की गई कच्ची मछली से बनता है। यह किफ़ायती संस्करण डिब्बाबंद टूना का उपयोग करता है लेकिन वही ताज़ा और चटपटा स्वाद देता है। सेविचे सॉल्टीन क्रैकर्स के साथ बढ़िया लगता है, लेकिन आप अपना पसंदीदा कोई भी क्रैकर इस्तेमाल कर सकते हैं या इसे हल्के दोपहर के भोजन के हिस्से के रूप में अकेले खा सकते हैं।",
"3","1/4 कप (लगभग 1 ⅓ औंस) + 6 क्रैकर्स",
["5 औंस कम सोडियम वाला, पानी में पैक टूना (पानी निथारा हुआ)","1 बड़ा चम्मच ताज़ा धनिया पत्ती (कटी हुई)","1/4 कप लाल प्याज़ (कटा हुआ)","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच बिना नमक वाली हर्ब सीज़निंग","3 बड़े चम्मच नीबू का रस","18 साबुत कम सोडियम वाले सॉल्टीन क्रैकर्स"],
["टूना, प्याज़, धनिया पत्ती, काली मिर्च और सीज़निंग मिश्रण को एक छोटे कटोरे में मिलाएँ। नीबू का रस डालें और सब कुछ अच्छी तरह मिलाएँ। ढककर परोसने से पहले कम से कम 2 घंटे मैरिनेट होने के लिए रेफ़्रिजरेटर में रखें।"]))
r.append(R(6579046,"मसूर की दाल का स्ट्यू",
"इस स्ट्यू में आप अलग-अलग तरह की मसूर के साथ प्रयोग कर सकते हैं: लाल, पीली या भूरी मसूर आज़माएँ।",
"6","1 कप",
["1 बड़ा चम्मच जैतून का तेल","1 मध्यम प्याज़ (टुकड़ों में कटा हुआ)","2 डंठल अजवाइन (सेलरी) (टुकड़ों में कटे हुए)","3 छोटी गाजर (या 2 मध्यम, छिली और टुकड़ों में कटी हुई)","1 मध्यम जैलापेनो मिर्च (बीज निकाली हुई और बारीक कटी हुई)","2 कली लहसुन (बारीक कटी हुई)","1 कप मसूर की दाल","4 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","1 कप पानी","1 पत्ता तेज पत्ता","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","4 कप बेबी पालक"],
["एक सूप के बर्तन में मध्यम-तेज़ आँच पर तेल डालें। प्याज़, अजवाइन, गाजर और जैलापेनो मिर्च डालें और प्याज़ के पारदर्शी होने तक भूनें, लगभग 5 मिनट।","लहसुन डालें और 1 मिनट और भूनें।","मसूर की दाल डालकर मिलाएँ और वेजिटेबल ब्रॉथ और पानी डालें।","तेज पत्ता, नमक (वैकल्पिक) और पिसी काली मिर्च डालें। उबाल आने दें। फिर, धीमी आँच कर दें। ढककर 40 मिनट धीमी आँच पर पकाएँ।","तेज पत्ता निकालें और पालक डालकर तब तक चलाएँ जब तक पालक गल न जाए।"]))
r.append(R(6579178,"जड़ वाली सब्ज़ियों के केक",
"ये केक एक बढ़िया साइड डिश या स्नैक बनते हैं और हमारे बीफ़ और शकरकंद स्ट्यू के साथ परोसने पर शानदार लगते हैं।",
"10","1 केक",
["1 बड़ा (लगभग 10 औंस) शकरकंद (छिला और कद्दूकस किया हुआ)","1 मध्यम (लगभग 10 औंस) रुतबागा (छिला और कद्दूकस किया हुआ)","2 छोटे (कुल लगभग 6 औंस) पार्सनिप (छिले और कद्दूकस किए हुए)","1 बड़ा अंडा","3 बड़े अंडे की सफ़ेदी","1/4 कप ताज़ा अजमोद (कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","1/2 कप साबुत गेहूँ का आटा","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["ओवन को 375 डिग्री F पर पहले से गरम करें। एक बड़ी बेकिंग शीट पर बेकिंग पेपर या सिलिकॉन मैट बिछाएँ।","सारी सामग्री को एक बड़े मिक्सिंग बाउल में मिलाएँ और अच्छी तरह मिलाएँ।","जड़ वाली सब्ज़ियों के मिश्रण को 1/2 कप के मापने वाले कप में दबाकर भरें और बेकिंग शीट पर उलट दें। केक का आकार देने के लिए हल्का दबाएँ। बाक़ी 9 केक के लिए यही प्रक्रिया दोहराएँ (आपकी बेकिंग शीट के आकार के अनुसार, आपको इन्हें कई बार में बनाना पड़ सकता है या दो बेकिंग शीट का उपयोग करना पड़ सकता है)।","केक के ऊपरी हिस्से पर कुकिंग स्प्रे करें और 35 मिनट बेक करें।","केक को पैन से निकालने से पहले थोड़ा ठंडा होने दें।"]))
r.append(R(6579304,"एवोकाडो, आर्टिचोक और मलाईदार शहद-सरसों की ड्रेसिंग के साथ ब्रसेल्स स्प्राउट्स सलाद",None,
"8","1/2 कप",
["2 कली लहसुन","2 बड़े चम्मच मेयोनेज़ (जैतून के तेल वाली)","4 छोटे चम्मच सफ़ेद सिरका","2 छोटे चम्मच शहद","2 छोटे चम्मच डिजॉन मस्टर्ड","1 छोटा चम्मच सूखी तुलसी","1/8 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च","1/2 पाउंड ताज़ी ब्रसेल्स स्प्राउट्स","6 औंस आर्टिचोक हार्ट्स (1 जार, नमकीन घोल में; चार टुकड़ों में कटे हुए, पानी निथारे और धुले हुए)","1/2 बड़ा एवोकाडो","1 रोमेन लेट्यूस","1 बड़ा चम्मच साबुत अलसी के बीज (भुने हुए)"],
["एक बड़े कटोरे में लहसुन, मेयोनेज़, सिरका, शहद, डिजॉन, तुलसी, नमक और काली मिर्च को फेंटकर मिलाएँ।","ब्रसेल्स स्प्राउट्स को छाँटकर पतली पट्टियों में काटें; ड्रेसिंग वाले कटोरे में डालें।","आर्टिचोक को मोटा-मोटा काटें और कटोरे में डालें।","एवोकाडो को मध्यम टुकड़ों में काटें और कटोरे में डालें।","लेट्यूस को निवाले के आकार के टुकड़ों में काटें या हाथ से तोड़ें और कटोरे में डालें; सलाद को मिलाने के लिए उछालें।","ऊपर से भुने हुए अलसी के बीज छिड़ककर परोसें।"]))
r.append(R(6580283,"केला चॉकलेट \"आइसक्रीम\"",
"यकीन करना मुश्किल है, लेकिन जमे हुए केले इस चार सामग्री वाली सॉफ़्ट-सर्व \"आइसक्रीम\" का बढ़िया आधार बनते हैं, जिसमें संतृप्त वसा कम है। इस जैसी मिठाइयाँ परोसते समय मात्रा पर नियंत्रण आसान बनाने के लिए छोटे रैमकिन या कप ख़रीदें।",
"5","1/2 कप",
["2 मध्यम केले","1/3 कप स्किम दूध","2 बड़े चम्मच कोको पाउडर","1 कप व्हिप्ड टॉपिंग (फ़ैट-फ़्री)"],
["केले छीलें और 1/4 इंच के गोल टुकड़ों में काटें। एक कटोरे में रखें और कम से कम 2 घंटे जमाएँ।","केले जम जाने के बाद, केले, दूध और कोको पाउडर को ब्लेंडर में डालें। चिकना होने तक ब्लेंड करें।","व्हिप्ड टॉपिंग को धीरे से मिलाएँ।","मिश्रण को फ़्रीज़र में रखने लायक डिब्बे में डालें और कम से कम 30 मिनट जमाएँ।","परोसने के लिए 1/2 कप के स्कूप में निकालें।"]))
r.append(R(6580857,"मलाईदार ताहिनी ड्रेसिंग के साथ छोले का सलाद",
"यह कुरकुरा और ताज़गी भरा छोले का सलाद घर पर बनी मलाईदार ताहिनी ड्रेसिंग के साथ मिलाया जाता है, जिससे एक सरल, पौधों पर आधारित भोजन बनता है जो स्वाद और फ़ाइबर में भरपूर है। छोले संतोषजनक प्रोटीन और धीरे पचने वाले कार्ब देते हैं जो रक्त ग्लूकोज़ (ब्लड शुगर) को स्थिर रखने में सहायक हो सकते हैं। यह एक पौष्टिक, बिना पकाए बनने वाला विकल्प है जो ख़ासकर उन लोगों के लिए उपयुक्त है जो ताज़ा, पेट भरने वाला दोपहर का भोजन चाहते हैं।",
"4","3 कप सलाद + 2 बड़े चम्मच ड्रेसिंग",
["1/4 कप ताहिनी","2 बड़े चम्मच नीबू का रस (ताज़ा)","1 कली लहसुन (कुचली हुई)","2 बड़े चम्मच पानी","1/4 छोटा चम्मच नमक","8 कप रोमेन लेट्यूस (कटा हुआ)","1 कप चेरी टमाटर (आधे कटे हुए)","1 कप खीरा (टुकड़ों में कटा हुआ)","1 कप डिब्बाबंद छोले (बिना नमक मिलाए, पानी निथारे और धुले हुए)","1/4 कप लाल प्याज़ (पतले स्लाइस में कटा हुआ)","2 बड़े चम्मच ताज़ा अजमोद (कटा हुआ)"],
["एक मध्यम कटोरे में ताहिनी, ताज़ा नीबू का रस, कुचला हुआ लहसुन और नमक मिलाएँ। धीरे-धीरे ठंडा पानी डालें और लगातार फेंटते रहें जब तक ड्रेसिंग चिकनी और धार डालने लायक गाढ़ेपन की न हो जाए।","एक अलग बड़े कटोरे में कटा हुआ रोमेन लेट्यूस, चेरी टमाटर, कटा हुआ खीरा और छोले मिलाएँ। स्लाइस किया हुआ लाल प्याज़ और कटा हुआ अजमोद डालें। सलाद पर ताहिनी ड्रेसिंग डालें।"]))
r.append(R(6581480,"टमाटर, तोरी और जैतून के साथ भुनी हुई कॉड मछली",
"कॉड एक मुलायम सफ़ेद मछली है जो अपने साथ पकाई गई चीज़ों का स्वाद ले लेती है। टमाटर और तोरी की मिठास और जैतून का नमकीनपन मिलकर इस भूमध्यसागरीय शैली के समुद्री भोजन को निश्चित रूप से पसंदीदा बना देंगे।",
"4","1 कॉड फ़िले + ½ कप सब्ज़ियाँ",
["1 कप रोमा (प्लम) टमाटर (टुकड़ों में कटे हुए)","2 बड़ी तोरी (टुकड़ों में कटी हुई)","1 मध्यम पीला प्याज़ (स्लाइस किया हुआ)","1/8 छोटा चम्मच कोशर नमक","1/8 छोटा चम्मच काली मिर्च (ताज़ी पिसी हुई)","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","2 कली लहसुन (कटी हुई)","1/4 कप कलामाता जैतून (गुठली निकाले और टुकड़ों में कटे हुए)","1/4 कप तुलसी (कटी हुई)","4 साबुत कॉड फ़िले (प्रत्येक 4-6 औंस)","2 बड़े चम्मच ताज़ा नीबू का रस"],
["ओवन को 425°F पर पहले से गरम करें।","टमाटर, तोरी और प्याज़ को एक बड़े बेकिंग डिश में रखें और नमक और काली मिर्च छिड़कें। ऊपर से जैतून का तेल डालें और लगभग 20 मिनट भूनें या जब तक सब्ज़ियाँ नरम न हो जाएँ।","ओवन से निकालें और लहसुन, जैतून और तुलसी मिलाएँ। कॉड फ़िले को सब्ज़ियों के ऊपर रखें और नमक और काली मिर्च छिड़कें। ऊपर से नीबू का रस डालें। वापस ओवन में रखें। लगभग 15 मिनट बेक करें, जब तक मछली पूरी तरह पक न जाए।"]))
r.append(R(6585792,"बिल्कुल सही भुनी हुई गाजर",
"यह साहसिक दावा हो सकता है, लेकिन हमारा मानना है कि गाजर को भूनने का यह बिल्कुल सही तरीका है! गाजर को हल्का कैरामेलाइज़ करने से इस सरल रेसिपी में एक लज़ीज़ भरपूरता और मिठास आती है और यह पूरे परिवार को ज़रूर पसंद आएगी।",
"4","1/2 कप",
["3 बड़े चम्मच जैतून का तेल","1 पाउंड गाजर (छिली हुई और 2–3 इंच की डंडियों में कटी हुई)","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच सूखा थाइम","1/4 छोटा चम्मच काली मिर्च"],
["एक बड़ी कड़ाही में मध्यम आँच पर जैतून का तेल गरम करें।","गाजर को कड़ाही में डालें और एक परत में फैलाएँ।","गाजर को 8–10 मिनट तक, बीच-बीच में चलाते हुए, तब तक भूनें जब तक वे नरम पर कुरकुरी और हल्की कैरामेलाइज़्ड न हो जाएँ।","गाजर पर नमक, थाइम और काली मिर्च डालें।"]))
r.append(R(6586304,"ब्रेज़्ड कोलार्ड, आलू और सफ़ेद बीन्स",
"क्लासिक इतालवी किसानों का व्यंजन, बीन्स और हरी पत्तेदार सब्ज़ियाँ, जिसमें ताज़े कोलार्ड ग्रीन्स और कैनेलिनी बीन्स और लाल मिर्च के फ़्लेक्स से थोड़ा तीखापन है। एक स्वादिष्ट साइड डिश या हल्का दोपहर का भोजन।",
"4","प्रति सर्विंग 1 1/2 कप आलू और हरी पत्तेदार सब्ज़ियाँ",
["1 पाउंड कोलार्ड ग्रीन्स","1 बड़ा चम्मच सफ़ेद सिरका ((सफ़ेद सिरका, सफ़ेद वाइन सिरका, या सेब का सिरका))","1 बड़ा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/4 कप पानी","1 छोटा पीला प्याज़ (बड़े टुकड़ों में कटा हुआ)","1 मध्यम आलू (बड़े टुकड़ों में कटा हुआ)","3 मध्यम टमाटर (टुकड़ों में कटे हुए)","1 छोटा चम्मच सूखा ओरेगानो","1, 15 औंस का डिब्बा कम सोडियम वाली सफ़ेद बीन्स (कैनेलिनी या ग्रेट नॉर्दर्न) (पानी निथारी और धुली हुई)","1/2 छोटा चम्मच कुटी हुई लाल मिर्च के फ़्लेक्स (वैकल्पिक)"],
["कोलार्ड तैयार करने के लिए: हर पत्ते को साफ़ करने के लिए ठंडे बहते पानी के नीचे धोएँ। हर पत्ते के बीच से डंठल काटें और पत्तों को छोटे टुकड़ों में काटें। डंठल फेंक दें। कटे हुए पत्तों को एक बड़े कटोरे में डालें और पानी से ढकें; थोड़ा सिरका डालें। 15 मिनट रहने दें।","एक बड़े भारी बर्तन (जैसे डच ओवन) को मध्यम आँच पर गरम करें और तेल डालें।","बर्तन में प्याज़ डालें और बीच-बीच में चलाते हुए पकाएँ, जब तक वे नरम होने न लगें, 4–5 मिनट।","पानी निथारे हुए कोलार्ड डालें और बीच-बीच में चलाते हुए पकाएँ, जब तक वे गल न जाएँ, 3–4 मिनट।","आलू, ओरेगानो, टमाटर और पानी डालें। धीमी आँच पर, हल्का ढककर, 20–30 मिनट पकाएँ, जब तक आलू काँटे से आसानी से न धँसने लगें।","सफ़ेद बीन्स डालकर मिलाएँ। चाहें तो कुटी हुई लाल मिर्च से सजाएँ।"]))
save(6,r)
